class DynamicArray {
  constructor(capacity = 4) {
    this.data = new Array(capacity);   // the fixed block
    this.length = 0;                   // elements in use
    this.capacity = capacity;          // slots available
  }
}

get(index) {
  if (index < 0 || index >= this.length) throw new RangeError('out of bounds');
  return this.data[index];
}

set(index, value) {
  if (index < 0 || index >= this.length) throw new RangeError('out of bounds');
  this.data[index] = value;
}

resize(newCapacity) {
  const bigger = new Array(newCapacity);
  for (let i = 0; i < this.length; i++) {
    bigger[i] = this.data[i];
  }
  this.data = bigger;
  this.capacity = newCapacity;
}

push(value) {
  if (this.length === this.capacity) {
    this.resize(this.capacity * 2);
  }
  this.data[this.length] = value;
  this.length++;
}

pop() {
  if (this.length === 0) throw new RangeError('empty');
  const value = this.data[this.length - 1];
  this.length--;

  if (this.length > 0 && this.length <= this.capacity / 4) {
    this.resize(Math.floor(this.capacity / 2));
  }
  return value;
}

insert(index, value) {
  if (index < 0 || index > this.length) throw new RangeError('out of bounds');
  if (this.length === this.capacity) this.resize(this.capacity * 2);

  for (let i = this.length; i > index; i--) {
    this.data[i] = this.data[i - 1];
  }
  this.data[index] = value;
  this.length++;
}
